 if(keys(a.design,['parameters','requirementLinks'],'design',e)){const p=a.design.parameters;if(keys(p,['frameLengthM','frameWidthM','trackM','bumperBottomM','bumperHeightM','bumperDepthM','height','reach','toolHeight','opening','phase'],'parameters',e)){for(const k of ['frameLengthM','frameWidthM','trackM'])num(p[k],.3,2,k,e);num(p.bumperBottomM,0,.5,'bumperBottomM',e);num(p.bumperHeightM,.01,.5,'bumperHeightM',e);num(p.bumperDepthM,.01,.3,'bumperDepthM',e);if(p.trackM>p.frameWidthM)e.push('track exceeds frame width');if(p.opening>=p.frameWidthM)e.push('opening must be narrower than frame');num(p.height,.22,2,'height',e);num(p.reach,0,1,'reach',e);num(p.toolHeight,0,2,'toolHeight',e);num(p.opening,.01,.69,'opening',e);enumv(p.phase,['start','deployed'],'phase',e)}if(!record(a.design.requirementLinks))e.push('requirementLinks must be object');else for(const [k,v]of Object.entries(a.design.requirementLinks)){if(!vs.has(k))e.push('unknown volume link '+k);links(v,rs,'volume requirementIds',e)}}
