export function assertDesign(a){const v=validateDesign(a);if(!v.valid)throw new Error(v.errors.join('; '));return a}
function sort(v){return Array.isArray(v)?v.map(sort):record(v)?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v}
export function canonicalStringify(a){assertDesign(a);return JSON.stringify(sort(a),null,2)+'\n'}
export function reviseDesign(a,mutator){assertDesign(a);const b=JSON.parse(canonicalStringify(a));mutator(b);b.parentRevision=a.revision;b.revision=a.revision+1;b.checks=[];return assertDesign(b)}
export function deriveGeometry(a){assertDesign(a);const p=a.design.parameters,L=p.frameLengthM,W=p.frameWidthM,D=p.bumperDepthM,Z=p.bumperBottomM+p.bumperHeightM/2,tx=p.reach===0?L/2-.105:L/2+p.reach-.1;const box=(id,size,center)=>({id,kind:'box',role:id,frame:'robot',size,center,requirementIds:a.design.requirementLinks[id]??[]});const volumes=[box('frame-plate',[L,W,.0508],[0,0,.1304]),box('body-envelope',[L,W,p.height],[0,0,p.height/2]),box('front-bumper',[D,W,p.bumperHeightM],[L/2+D/2,0,Z]),box('rear-bumper',[D,W,p.bumperHeightM],[-L/2-D/2,0,Z]),box('left-bumper',[L+2*D,D,p.bumperHeightM],[0,W/2+D/2,Z]),box('right-bumper',[L+2*D,D,p.bumperHeightM],[0,-W/2-D/2,Z]),box('tool',[.2,.35,.15],[tx,0,p.toolHeight]),...(p.reach>0?[box('reach',[p.reach,.35,.15],[L/2+p.reach/2,0,p.toolHeight])]:[])];const cut={enabled:a.operations[0].enabled,id:a.operations[0].id,targetIds:a.operations[0].targetIds,center:[(L/2-.0508)/2,0,.11],size:[L/2-.0508,p.opening,.22],frame:'robot',kind:'box'};return {volumes,openings:[cut],field:{length:16.54175,width:8.21055},speaker:{width:1.051052,lowEdge:[0,0,1.984502],highEdge:[-.459994,0,2.10566],tolerance:.0127,frame:'target'},note:{majorRadius:.1524,minorRadius:.0254,center:[3.1,.75,.0254],frame:'world'}}}
export function worldPoint(point,pose){const t=pose.headingDeg*Math.PI/180,c=Math.cos(t),s=Math.sin(t);return [pose.x+c*point[0]-s*point[1],pose.y+s*point[0]+c*point[1],pose.z+point[2]]}
export function exportCad(a){const g=deriveGeometry(a),v=x=>JSON.stringify(x),lines=['// Editable spatial blockout derivative. Output units: millimetres; source artifact: metres. Not fabrication-ready.','// Artifact '+a.id+' revision '+a.revision+'; edit the companion JSON to preserve traceability.','$fn=48;','scale([1000,1000,1000]) {',`module robot_frame(){translate(${v([a.frames.robot.x,a.frames.robot.y,a.frames.robot.z])}) rotate([0,0,${a.frames.robot.headingDeg}]) children();}`];for(const b of g.volumes){lines.push('// '+b.id,'robot_frame() '+(g.openings[0].enabled&&g.openings[0].targetIds.includes(b.id)?`difference(){ translate(${v(b.center)}) cube(${v(b.size)},center=true); translate(${v(g.openings[0].center)}) cube(${v(g.openings[0].size)},center=true); }`:`translate(${v(b.center)}) cube(${v(b.size)},center=true);`))}const n=g.note;lines.push('// NOTE reference (not a held piece)',`translate(${v(n.center)}) rotate_extrude() translate([${n.majorRadius},0,0]) circle(r=${n.minorRadius});`);lines.push('}');return lines.join('\n')+'\n'}

