export const editArtifact=reviseDesign;

export function spatialChecks(a){const g=deriveGeometry(a),p=a.design.parameters;return [
{id:'frame-perimeter',inputRevision:a.revision,status:2*(p.frameLengthM+p.frameWidthM)<=3.048?'pass':'fail',scope:'2024 nominal frame perimeter screen only; taut-string perimeter must be established.',requirementIds:[]},
{id:'bumper-zone',inputRevision:a.revision,status:p.bumperBottomM+p.bumperHeightM<=.1905?'pass':'fail',scope:'2024 R402 vertical envelope only; coverage, attachments and material requirements not certified.',requirementIds:[]},
{id:'height',inputRevision:a.revision,status:Math.max(p.height,p.toolHeight+.075)<=1.2192?'pass':'fail',scope:'2024 G413 height screen applies during play as well as starting; full robot omitted.',requirementIds:[]},
{id:'stow',inputRevision:a.revision,status:p.phase==='start'&&p.reach>0?'fail':'unknown',scope:'Reserved volumes are not a swept mechanism or starting configuration qualification.',requirementIds:[]},
{id:'bumper-support',inputRevision:a.revision,status:'unknown',scope:'2024 R410 backing gap/end support review required. The bay retains a provisional 50.8 mm front support strip, not qualified material or attachment geometry.',requirementIds:[]},
{id:'bumper-coverage',inputRevision:a.revision,status:'unknown',scope:'Chassis cuts preserve modeled front bumper. 2024 R401 requires whole perimeter coverage (adjacent gaps less than 0.5 in); R403 prohibits articulation. Full attachment/coverage review required.',requirementIds:[]}
]}
export function rehearsalBudget(a){assertDesign(a);const r=a.rehearsal,wrap=d=>Math.atan2(Math.sin(d*Math.PI/180),Math.cos(d*Math.PI/180))*180/Math.PI;let drive=0,turn=0,actions=0;for(let i=1;i<r.route.length;i++){const p=r.route[i-1],q=r.route[i],d=Math.hypot(q.x-p.x,q.y-p.y),bearing=d?Math.atan2(q.y-p.y,q.x-p.x)*180/Math.PI:p.headingDeg;drive+=d/r.driveSpeedMps;turn+=(Math.abs(wrap(bearing-p.headingDeg))+Math.abs(wrap(q.headingDeg-bearing)))/r.turnSpeedDegps;actions+=q.action==='none'?0:r.actionDurations[q.action]}return {driveS:drive,turnS:turn,actionS:actions,totalS:drive+turn+actions,basis:r.basis,scope:'kinematic planning budget, not physical cycle-time prediction'}}
